-- Generated by node scripts/generate-notebook-migration.js from the two independent Web learning paths.
insert into public.nodes (slug, label, description, best_practices, naming_conventions, study_urls)
values (
  'web-professions',
  'Professioni nel Web',
  'Ruoli e competenze dei team che progettano, sviluppano, verificano e mantengono prodotti Web.',
  array[]::text[],
  array[]::text[],
  '[{"label":"MDN: Getting started with the Web","url":"https://developer.mozilla.org/docs/Learn/Getting_started_with_the_web"}]'::jsonb
)
on conflict (slug) do nothing;

insert into public.node_categories (node_id, category, is_primary)
select id, 'tools', true from public.nodes where slug = 'web-professions'
on conflict (node_id, category) do nothing;

insert into public.nodes (slug, label, description, best_practices, naming_conventions, study_urls)
values (
  'web-infrastructure',
  'Server e infrastruttura Web',
  'Server, data center, server farm, reti, bilanciamento e modelli cloud che mantengono disponibili i servizi Web.',
  array[]::text[],
  array[]::text[],
  '[{"label":"MDN: How the Web Works","url":"https://developer.mozilla.org/docs/Learn/Common_questions/Web_mechanisms/How_does_the_Internet_work"},{"label":"Google Cloud: Cloud Computing","url":"https://cloud.google.com/learn/what-is-cloud-computing"}]'::jsonb
)
on conflict (slug) do nothing;

insert into public.node_categories (node_id, category, is_primary)
select id, 'devops', true from public.nodes where slug = 'web-infrastructure'
on conflict (node_id, category) do nothing;

insert into public.node_content_sections (node_id, sort_order, title, type, payload)
select id, 0, 'Professioni nel Web', 'text', jsonb_build_object('text', 'Frontend e backend developer costruiscono interfacce e servizi; full-stack developer lavorano su entrambi gli ambiti. Web designer e professionisti UI/UX progettano interfacce e flussi. QA verifica la qualità; DevOps e sistemisti curano rilascio, sistemi e infrastruttura. Le responsabilità possono sovrapporsi e cambiano in base al team.')
from public.nodes
where slug = 'web-professions'
  and not exists (
    select 1 from public.node_content_sections
    where node_id = public.nodes.id and title = 'Professioni nel Web'
  );

insert into public.node_content_sections (node_id, sort_order, title, type, payload)
select id, 0, 'Server e infrastruttura Web', 'text', jsonb_build_object('text', 'Server indica il ruolo di un sistema che offre un servizio a un client; può essere un computer fisico, una macchina virtuale o una risorsa cloud. Il web server riceve richieste HTTP, mentre l''applicazione esegue la logica del prodotto. Data center e server farm ospitano e coordinano macchine, reti, alimentazione e raffreddamento. Bilanciamento e ridondanza aiutano a gestire carico e disponibilità; i backup servono a recuperare dati. I modelli IaaS, PaaS e serverless differiscono per quanta infrastruttura gestisce il provider.')
from public.nodes
where slug = 'web-infrastructure'
  and not exists (
    select 1 from public.node_content_sections
    where node_id = public.nodes.id and title = 'Server e infrastruttura Web'
  );

insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'web-professions', 'Scopri cosa fanno frontend e backend developer, designer, QA, DevOps e sistemisti e come collaborano in un progetto.', n.id,
  case when n.id is null then 'web-professions' else null end,
  convert_from(decode('', 'base64'), 'UTF8')::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'web-professions'
on conflict (slug) do nothing;

insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'web-infrastructure', 'Distingui server e web server e scopri data center, server farm, bilanciamento, continuità del servizio e cloud.', n.id,
  case when n.id is null then 'web-infrastructure' else null end,
  convert_from(decode('', 'base64'), 'UTF8')::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'web-infrastructure'
on conflict (slug) do nothing;
